export type DocSection = { id: string; title: string; html: string };
export type DocArticle = {
  path: string;
  title: string;
  description: string;
  eyebrow: string;
  product?: string;
  productHref?: string;
  keywords: string;
  sections: DocSection[];
};

const affiliateUrl = 'https://billing.sparkedhost.com/aff.php?aff=3352';

const esc = (value: string) => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const code = (value: string, label = '') => `<div class="code-wrap">${label ? `<div class="code-label">${label}</div>` : ''}<pre class="code"><code>${esc(value)}</code></pre></div>`;
const callout = (tone: 'info' | 'important' | 'warning' | 'security' | 'success' | 'example', title: string, body: string) => `<aside class="callout ${tone}"><strong>${title}</strong><p>${body}</p></aside>`;
const steps = (items: string[]) => `<ol class="steps">${items.map(item => `<li>${item}</li>`).join('')}</ol>`;
const checklist = (items: string[]) => `<ul class="checklist">${items.map(item => `<li>${item}</li>`).join('')}</ul>`;
const table = (headers: string[], rows: string[][]) => `<div class="table-scroll"><table><thead><tr>${headers.map(header => `<th>${header}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const faq = (items: [string, string][]) => `<div class="faq">${items.map(([question, answer]) => `<details><summary>${question}</summary><p>${answer}</p></details>`).join('')}</div>`;
const config = (rows: [string, string, string][]) => table(['Setting', 'What to enter', 'What it controls'], rows.map(([name, value, meaning]) => [`<code>${name}</code>`, value, meaning]));
const commands = (names: string[], notes: Record<string, string> = {}) => table(['Command', 'Purpose'], names.map(name => [`<code>/${name}</code>`, notes[name] || `Runs the ${name.replaceAll('-', ' ')} workflow. Discord displays the available parameters when the command is selected.`]));
const section = (id: string, title: string, html: string): DocSection => ({ id, title, html });
const article = (path: string, title: string, description: string, eyebrow: string, keywords: string, sections: DocSection[], product?: string, productHref?: string): DocArticle => ({ path, title, description, eyebrow, keywords, sections, product, productHref });

