export const docsArticles = [...shared, ...scarlett, ...manager, ...dmRelay, ...leo, ...iaa, ...aliases];
export const docsByPath = new Map(docsArticles.map(item => [item.path, item]));

const groups = [
  { label: 'Documentation', links: [['Documentation Home', ''], ['Getting Started', 'getting-started'], ['Hosting', 'hosting'], ['Discord Bot Setup', 'discord'], ['Database Setup', 'databases'], ['Environment Variables', 'environment-variables'], ['Security', 'security'], ['Troubleshooting', 'troubleshooting'], ['FAQ', 'faq'], ['Glossary', 'glossary']] },
  ...documentedProducts.map(product => ({ label: product.name, links: docsArticles.filter(item => item.path === product.slug || item.path.startsWith(`${product.slug}/`)).map(item => [item.title.replace(`${product.name} `, '').replace(' Documentation', 'Overview'), item.path]) }))
] as { label: string; links: string[][] }[];

export const docsNavigation = groups;
export const docsSearchEntries = docsArticles.flatMap(item => [
  { title: item.title, excerpt: item.description, category: item.product || item.eyebrow, href: `/docs/${item.path}${item.path ? '/' : ''}`, version: 'Current', keywords: item.keywords },
  ...item.sections.map(sectionItem => ({ title: `${item.title}: ${sectionItem.title}`, excerpt: `${item.description} ${item.keywords}`, category: item.product || item.eyebrow, href: `/docs/${item.path}${item.path ? '/' : ''}#${sectionItem.id}`, version: 'Current', keywords: `${item.keywords} ${sectionItem.title}` }))
]);

export function adjacentDocs(path: string) {
  const visible = docsArticles.filter(item => !['privacy', 'terms', 'contact'].includes(item.path));
  const index = visible.findIndex(item => item.path === path);
  return { previous: index > 0 ? visible[index - 1] : undefined, next: index >= 0 && index < visible.length - 1 ? visible[index + 1] : undefined };
}
